# ---------------------------------------------------------------------------
# Projects per persona. Each project: slug, case-study title, codename (repo name), casual
# description (how proposals/reviews mention it), industry, problem, named skills, implied skills,
# result metric template, outcome.
# ---------------------------------------------------------------------------

def _p(slug, title, codename, casual, industry, problem, named, implied, result, outcome="delivered"):
    return dict(slug=slug, title=title, codename=codename, casual=casual, industry=industry,
                problem=problem, named=named, implied=implied, result=result, outcome=outcome)


